//
// The bundle (bi_robotics/build/chartkitchen_superset.py bundle()) is this file after vendor/powerbi-global.js, the
// unchanged ChartKitchen bundle and plugins/chartkitchen-host/host.js. A chart's params name its query -- groupby
// (dimension columns of the Cube view), metrics (saved MEASURE() metrics), adhoc_filters -- and carry the ChartKitchen
// settings in `chartkitchen` (JSON, written from the model): roles in the result's column names, and the objects.
// Superset runs the query with the dashboard's filters; the rows go to host.js as {columns, rows}.

const KEY = "bir_chartkitchen";
const core = window["__superset__/@superset-ui/core"];
